mapper.select:
SELECT
    message_id,
    message_type,
    receiver_user_type,
    receiver_user_id,
    data_id,
    title,
    content,
    read_flag,
    read_time,
    create_time
FROM t_message


        AND (INSTR(title, #{query.searchWord}) OR INSTR(content, #{query.searchWord}))


        AND message_type = #{query.messageType}


        AND read_flag = #{query.readFlag}


        AND receiver_user_id = #{query.receiverUserId}


        AND receiver_user_type = #{query.receiverUserType}


        AND DATE_FORMAT(create_time, '%Y-%m-%d') >= #{query.startDate}


        AND DATE_FORMAT(create_time, '%Y-%m-%d') <= #{query.endDate}


ORDER BY create_time DESC

mapper.update:
UPDATE t_message
SET
    read_flag = #{readFlag},
    read_time = NOW()
WHERE message_id = #{messageId}
  AND receiver_user_type = #{receiverUserType}
  AND receiver_user_id = #{receiverUserId}

